with src as (
  select v.chapter_id, v.level_id, v.atom_key, v.atom_type, v.atom_order, v.title, v.body::jsonb as body
  from (values
  -- 901 Cell
  (901,'govt_technical','cell-concept','concept',1,'कोशिका — SSC JE / RRB JE',$j${"note":"परीक्षा में प्रोकैरियोटिक और यूकैरियोटिक कोशिका का अंतर अक्सर पूछा जाता है।","text":"कोशिका जीवन की संरचनात्मक और क्रियात्मक इकाई है। प्रोकैरियोट (जैसे जीवाणु) में झिल्ली-बद्ध नाभिक नहीं होता, यूकैरियोट (पादप और जंतु) में होता है। माइटोकॉन्ड्रिया ATP बनाकर ऊर्जा देता है, इसलिए इसे कोशिका का पावरहाउस कहते हैं।"}$j$),
  (901,'govt_technical','cell-formula','formula',2,'कोशिका की ऊर्जा मुद्रा',$j${"formula":"ATP (एडेनोसिन ट्राइफॉस्फेट)","explanation":"माइटोकॉन्ड्रिया में श्वसन से ATP बनता है, जो कोशिका की मुख्य ऊर्जा मुद्रा है"}$j$),
  (901,'govt_technical','cell-example','example',3,'Numerical (JE style)',$j${"question":"परिपक्व मानव लाल रक्त कोशिका (RBC) में नाभिक होता है या नहीं?","solution":"परिपक्व RBC में नाभिक नहीं होता, जिससे अधिक हीमोग्लोबिन रखने की जगह मिलती है","answer":"नहीं होता"}$j$),
  (901,'govt_technical','cell-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"कोशिका का पावरहाउस किसे कहते हैं?","options":["माइटोकॉन्ड्रिया","राइबोसोम","लाइसोसोम","गॉल्जी काय"],"answer":0,"explanation":"माइटोकॉन्ड्रिया श्वसन द्वारा ATP बनाकर ऊर्जा देता है।"},{"q":"पादप कोशिका में कौन सी संरचना जंतु कोशिका में नहीं होती?","options":["कोशिका भित्ति","कोशिका झिल्ली","नाभिक","माइटोकॉन्ड्रिया"],"answer":0,"explanation":"कोशिका भित्ति (सेल्युलोज की) केवल पादप कोशिका में होती है।"}]}$j$),
  (901,'govt_basic','cell-concept','concept',1,'कोशिका',$j${"note":"परीक्षा में कोशिका को जीवन की इकाई कहा जाता है।","text":"हर जीव कोशिकाओं से बना है। कुछ जीव एक ही कोशिका के होते हैं (जैसे अमीबा), और कुछ कई कोशिकाओं के (जैसे मनुष्य)। कोशिका के मुख्य भाग कोशिका झिल्ली, कोशिका द्रव्य और नाभिक हैं।"}$j$),
  (901,'govt_basic','cell-formula','formula',2,'कोशिका के भाग',$j${"formula":"कोशिका झिल्ली + कोशिका द्रव्य + नाभिक","explanation":"पादप कोशिका में अतिरिक्त कोशिका भित्ति और हरित लवक होते हैं"}$j$),
  (901,'govt_basic','cell-example','example',3,'उदाहरण',$j${"question":"अमीबा किस प्रकार का जीव है?","solution":"अमीबा केवल एक कोशिका से बना होता है, इसलिए यह एककोशिकीय है","answer":"एककोशिकीय"}$j$),
  (901,'govt_basic','cell-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"कोशिका का नियंत्रण केंद्र किसे कहते हैं?","options":["नाभिक","राइबोसोम","लाइसोसोम","रिक्तिका"],"answer":0,"explanation":"नाभिक में DNA होता है, जो कोशिका की गतिविधियों को नियंत्रित करता है।"},{"q":"पौधों को हरा रंग किस अंग से मिलता है?","options":["हरित लवक (क्लोरोप्लास्ट)","माइटोकॉन्ड्रिया","नाभिक","रिक्तिका"],"answer":0,"explanation":"हरित लवक में क्लोरोफिल होता है, जो प्रकाश संश्लेषण में मदद करता है।"}]}$j$),
  (901,null,'cell-diagram','svg',5,'जंतु और पादप कोशिका',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><ellipse cx='90' cy='60' rx='60' ry='45' fill='#bbf7d0' stroke='#14b8a6' stroke-width='3'/><circle cx='90' cy='60' r='16' fill='#60a5fa'/><ellipse cx='210' cy='60' rx='55' ry='45' fill='#fef3c7' stroke='#f59e0b' stroke-width='2'/><circle cx='210' cy='60' r='16' fill='#60a5fa'/><text x='90' y='115' text-anchor='middle' fill='#64748b' font-size='11'>पादप कोशिका</text><text x='210' y='115' text-anchor='middle' fill='#64748b' font-size='11'>जंतु कोशिका</text></svg>","caption":"पादप कोशिका में कोशिका भित्ति होती है, जंतु कोशिका में नहीं"}$j$),
  -- 902 Tissues
  (902,'govt_technical','tiss-concept','concept',1,'ऊतक — SSC JE / RRB JE',$j${"note":"परीक्षा में पादप के जाइलम और फ्लोएम के कार्य अक्सर पूछे जाते हैं।","text":"समान कार्य करने वाली कोशिकाओं के समूह को ऊतक कहते हैं। पादप ऊतक: विभज्योतकी (वृद्धि), स्थायी ऊतक (पैरेनकाइमा, कोलेनकाइमा, स्क्लेरेनकाइमा), जाइलम (जल व खनिज ऊपर ले जाता है) और फ्लोएम (भोजन नीचे ले जाता है)। जंतु ऊतक: उपकला, संयोजी, पेशी और तंत्रिका।"}$j$),
  (902,'govt_technical','tiss-formula','formula',2,'जाइलम और फ्लोएम के कार्य',$j${"formula":"जाइलम: जल और खनिज ऊपर · फ्लोएम: भोजन (शर्करा) नीचे","explanation":"दोनों मिलकर संवहन ऊतक (vascular bundle) बनाते हैं"}$j$),
  (902,'govt_technical','tiss-example','example',3,'Numerical (JE style)',$j${"question":"रक्त किस प्रकार का ऊतक है?","solution":"रक्त में कोशिकाएँ तरल प्लाज्मा में होती हैं; यह संयोजी ऊतक (connective tissue) है","answer":"संयोजी ऊतक"}$j$),
  (902,'govt_technical','tiss-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"पादप में जल और खनिज लवण जड़ से पत्ती तक कौन सा ऊतक ले जाता है?","options":["जाइलम","फ्लोएम","कॉर्क","एपिडर्मिस"],"answer":0,"explanation":"जाइलम जल और खनिज लवणों का ऊपर की ओर संवहन करता है।"},{"q":"हृदय की दीवार किस प्रकार के ऊतक से बनती है?","options":["पेशी ऊतक","उपकला ऊतक","संयोजी ऊतक","तंत्रिका ऊतक"],"answer":0,"explanation":"हृदय की दीवार हृदय पेशी (cardiac muscle) से बनी होती है।"}]}$j$),
  (902,'govt_basic','tiss-concept','concept',1,'ऊतक',$j${"note":"परीक्षा में ऊतकों के नाम और कार्य पूछे जाते हैं।","text":"एक जैसे काम करने वाली कोशिकाएँ मिलकर ऊतक बनाती हैं। मनुष्य में चार मुख्य ऊतक होते हैं: उपकला, संयोजी, पेशी और तंत्रिका ऊतक।"}$j$),
  (902,'govt_basic','tiss-formula','formula',2,'मानव के मुख्य ऊतक',$j${"formula":"उपकला + संयोजी + पेशी + तंत्रिका","explanation":"हर ऊतक का कार्य अलग है: सुरक्षा, सहारा, गति और संदेश"}$j$),
  (902,'govt_basic','tiss-example','example',3,'उदाहरण',$j${"question":"मांसपेशियों में संकुचन करने वाला ऊतक कौन सा है?","solution":"मांसपेशियाँ पेशी ऊतक से बनी हैं, जो संकुचन से गति कराता है","answer":"पेशी ऊतक"}$j$),
  (902,'govt_basic','tiss-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"संदेश भेजने और ग्रहण करने का काम कौन सा ऊतक करता है?","options":["तंत्रिका ऊतक","पेशी ऊतक","संयोजी ऊतक","उपकला ऊतक"],"answer":0,"explanation":"तंत्रिका ऊतक (न्यूरॉन) विद्युत संकेतों से संदेश भेजता है।"},{"q":"त्वचा की बाहरी परत किस ऊतक से बनती है?","options":["उपकला ऊतक","संयोजी ऊतक","पेशी ऊतक","तंत्रिका ऊतक"],"answer":0,"explanation":"त्वचा की बाहरी परत उपकला ऊतक से बनी है, जो सुरक्षा देती है।"}]}$j$),
  (902,null,'tiss-diagram','svg',5,'पादप के संवहन ऊतक',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><rect x='80' y='20' width='40' height='80' fill='#60a5fa' rx='4'/><text x='100' y='112' text-anchor='middle' fill='#64748b' font-size='11'>जाइलम (जल ↑)</text><rect x='180' y='20' width='40' height='80' fill='#f59e0b' rx='4'/><text x='200' y='112' text-anchor='middle' fill='#64748b' font-size='11'>फ्लोएम (भोजन ↓)</text></svg>","caption":"जाइलम और फ्लोएम पौधे में पदार्थों का संवहन करते हैं"}$j$),
  -- 903 Animal Kingdom
  (903,'govt_technical','anim-concept','concept',1,'जंतु जगत — SSC JE / RRB JE',$j${"note":"परीक्षा में कशेरुकी और अकशेरुकी के अंतर और स्तनधारी के लक्षण अक्सर पूछे जाते हैं।","text":"जंतु जगत में अकशेरुकी (रीढ़ रहित) और कशेरुकी (रीढ़ युक्त) होते हैं। कशेरुकी के पाँच वर्ग: मत्स्य, उभयचर, सरीसृप, पक्षी और स्तनधारी। स्तनधारियों में बाल और दुग्ध ग्रंथियाँ होती हैं, और हृदय चार कक्षों का होता है।"}$j$),
  (903,'govt_technical','anim-formula','formula',2,'कशेरुकी वर्ग',$j${"formula":"मत्स्य → उभयचर → सरीसृप → पक्षी → स्तनधारी","explanation":"ये वर्ग विकास के क्रम के अनुसार आमतौर पर बताए जाते हैं"}$j$),
  (903,'govt_technical','anim-example','example',3,'Numerical (JE style)',$j${"question":"मेंढक किस वर्ग का जंतु है और उसकी विशेषता क्या है?","solution":"मेंढक उभयचर है; यह जल और स्थल दोनों में रहता है और रूपांतरण (metamorphosis) से गुजरता है","answer":"उभयचर (Amphibia)"}$j$),
  (903,'govt_technical','anim-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"स्तनधारियों की सबसे प्रमुख पहचान क्या है?","options":["दुग्ध ग्रंथियाँ","पंख","शल्क","गलफड़े"],"answer":0,"explanation":"दुग्ध ग्रंथियाँ स्तनधारियों की पहचान है, जिससे शिशु को दूध मिलता है।"},{"q":"पक्षियों के शरीर पर क्या होता है?","options":["पंख","बाल","शल्क","रोम-कूप रहित त्वचा"],"answer":0,"explanation":"पक्षियों के शरीर पर पंख होते हैं, जो उड़ने में मदद करते हैं।"}]}$j$),
  (903,'govt_basic','anim-concept','concept',1,'जंतु वर्गीकरण',$j${"note":"परीक्षा में मेंढक, साँप, पक्षी और मनुष्य का वर्ग पूछा जाता है।","text":"जंतुओं को उनकी बनावट के आधार पर बाँटा जाता है। रीढ़ की हड्डी वाले कशेरुकी और उसके बिना अकशेरुकी होते हैं। मनुष्य स्तनधारी है।"}$j$),
  (903,'govt_basic','anim-formula','formula',2,'रीढ़ की हड्डी',$j${"formula":"कशेरुकी = रीढ़ की हड्डी युक्त","explanation":"उदाहरण: मछली, मेंढक, साँप, पक्षी, मनुष्य · अकशेरुकी: कीट, केंचुआ, घोंघा"}$j$),
  (903,'govt_basic','anim-example','example',3,'उदाहरण',$j${"question":"केंचुआ कशेरुकी है या अकशेरुकी?","solution":"केंचुए में रीढ़ की हड्डी नहीं होती, इसलिए यह अकशेरुकी है","answer":"अकशेरुकी"}$j$),
  (903,'govt_basic','anim-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"इनमें से कौन सा जंतु स्तनधारी है?","options":["व्हेल","मछली","साँप","मेंढक"],"answer":0,"explanation":"व्हेल बाल रहित होने पर भी स्तनधारी है, क्योंकि वह बच्चों को दूध पिलाती है।"},{"q":"साँप किस वर्ग का जंतु है?","options":["सरीसृप","उभयचर","पक्षी","मत्स्य"],"answer":0,"explanation":"साँप शल्कयुक्त त्वचा वाला सरीसृप है।"}]}$j$),
  (903,null,'anim-diagram','svg',5,'कशेरुकी वर्ग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><g font-size='11' fill='#0f172a' text-anchor='middle'><rect x='10' y='40' width='50' height='30' fill='#60a5fa' rx='4'/><text x='35' y='60'>मत्स्य</text><rect x='70' y='40' width='50' height='30' fill='#14b8a6' rx='4'/><text x='95' y='60'>उभयचर</text><rect x='130' y='40' width='50' height='30' fill='#f59e0b' rx='4'/><text x='155' y='60'>सरीसृप</text><rect x='190' y='40' width='50' height='30' fill='#fca5a5' rx='4'/><text x='215' y='60'>पक्षी</text><rect x='250' y='40' width='45' height='30' fill='#c4b5fd' rx='4'/><text x='272' y='60'>स्तनी</text></g><text x='150' y='110' text-anchor='middle' fill='#64748b' font-size='11'>पाँच कशेरुकी वर्ग</text></svg>","caption":"कशेरुकी जंतुओं के पाँच मुख्य वर्ग"}$j$),
  -- 904 Plant Kingdom
  (904,'govt_technical','plnt-concept','concept',1,'पादप जगत — SSC JE / RRB JE',$j${"note":"परीक्षा में जिम्नोस्पर्म और एंजियोस्पर्म का अंतर और बीजपत्रों की संख्या अक्सर पूछी जाती है।","text":"पादप जगत के वर्ग: शैवाल (सरल, जलीय), ब्रायोफाइटा (काई, संवहन ऊतक नहीं), टेरिडोफाइटा (फर्न, संवहन ऊतक है पर बीज नहीं), जिम्नोस्पर्म (नग्नबीजी, जैसे चीड़) और एंजियोस्पर्म (आवृतबीजी, फूल वाले)। एंजियोस्पर्म में बीज फल के अंदर होते हैं।"}$j$),
  (904,'govt_technical','plnt-formula','formula',2,'आवृतबीजी के वर्ग',$j${"formula":"एंजियोस्पर्म = मोनोकॉट (एक बीजपत्र) + डाइकॉट (दो बीजपत्र)","explanation":"उदाहरण: मक्का, गेहूँ (मोनोकॉट) · चना, सरसों (डाइकॉट)"}$j$),
  (904,'govt_technical','plnt-example','example',3,'Numerical (JE style)',$j${"question":"चीड़ (Pine) किस वर्ग का पौधा है और उसका बीज कैसा होता है?","solution":"चीड़ जिम्नोस्पर्म है; इसके बीज खुले शंकु (cone) में नग्न रहते हैं","answer":"जिम्नोस्पर्म, नग्न बीज"}$j$),
  (904,'govt_technical','plnt-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"गेहूँ और मक्का किस प्रकार के आवृतबीजी हैं?","options":["मोनोकॉट (एक बीजपत्री)","डाइकॉट (द्विबीजपत्री)","जिम्नोस्पर्म","ब्रायोफाइटा"],"answer":0,"explanation":"गेहूँ और मक्का में एक बीजपत्र होता है, इसलिए ये मोनोकॉट हैं।"},{"q":"काई (मॉस) किस समूह में आती है?","options":["ब्रायोफाइटा","टेरिडोफाइटा","जिम्नोस्पर्म","एंजियोस्पर्म"],"answer":0,"explanation":"काई ब्रायोफाइटा समूह में आती है और इसमें संवहन ऊतक नहीं होते।"}]}$j$),
  (904,'govt_basic','plnt-concept','concept',1,'पौधों के समूह',$j${"note":"परीक्षा में फूल वाले और बिना फूल वाले पौधों का अंतर पूछा जाता है।","text":"पौधे दो मुख्य समूहों में हैं: बिना फूल वाले (जैसे काई, फर्न) और फूल वाले (आवृतबीजी)। फूल वाले पौधों के बीज फल के अंदर बनते हैं।"}$j$),
  (904,'govt_basic','plnt-formula','formula',2,'मुख्य पहचान',$j${"formula":"फूल वाले = आवृतबीजी (बीज फल में)","explanation":"नग्नबीजी (जैसे चीड़) में बीज खुले रहते हैं"}$j$),
  (904,'govt_basic','plnt-example','example',3,'उदाहरण',$j${"question":"आम का पौधा किस समूह में आता है?","solution":"आम फूल और फल वाला पौधा है, जिसके बीज फल के अंदर होते हैं","answer":"आवृतबीजी (एंजियोस्पर्म)"}$j$),
  (904,'govt_basic','plnt-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"बीज फल के अंदर बनने वाले पौधे क्या कहलाते हैं?","options":["आवृतबीजी","नग्नबीजी","शैवाल","काई"],"answer":0,"explanation":"आवृतबीजी पौधों के बीज फल के अंदर ढके रहते हैं।"},{"q":"शैवाल किस प्रकार के पौधे हैं?","options":["सरल और अधिकतर जलीय","फूल वाले","वृक्ष","झाड़ियाँ"],"answer":0,"explanation":"शैवाल सरल, अधिकतर जल में रहने वाले पौधे हैं।"}]}$j$),
  (904,null,'plnt-diagram','svg',5,'पौधे का भाग',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><line x1='150' y1='110' x2='150' y2='50' stroke='#64748b' stroke-width='4'/><circle cx='150' cy='35' r='25' fill='#86efac'/><circle cx='120' cy='60' r='12' fill='#86efac'/><circle cx='180' cy='60' r='12' fill='#86efac'/><text x='150' y='118' text-anchor='middle' fill='#64748b' font-size='11'>पादप: तना, पत्ती और फूल</text></svg>","caption":"पौधे की संरचना में तना और पत्तियाँ मुख्य भाग हैं"}$j$),
  -- 905 Nutrition
  (905,'govt_technical','nutr-concept','concept',1,'पोषण — SSC JE / RRB JE',$j${"note":"परीक्षा में प्रकाश संश्लेषण का समीकरण और विटामिन की कमी के रोग अक्सर पूछे जाते हैं।","text":"स्वपोषी (पौधे) प्रकाश संश्लेषण से अपना भोजन बनाते हैं; परपोषी (जंतु) भोजन के लिए दूसरों पर निर्भर रहते हैं। भोजन में कार्बोहाइड्रेट, प्रोटीन, वसा, विटामिन और खनिज होते हैं। विटामिन C की कमी से स्कर्वी और विटामिन D की कमी से रिकेट्स होता है।"}$j$),
  (905,'govt_technical','nutr-formula','formula',2,'प्रकाश संश्लेषण का समीकरण',$j${"formula":"6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (सूर्य का प्रकाश, क्लोरोफिल)","explanation":"पौधा CO₂ और पानी से ग्लूकोज़ बनाता है और ऑक्सीजन छोड़ता है"}$j$),
  (905,'govt_technical','nutr-example','example',3,'Numerical (JE style)',$j${"question":"प्रकाश संश्लेषण में 1 mol ग्लूकोज़ (C₆H₁₂O₆) बनने पर कितने mol ऑक्सीजन निकलेगी?","solution":"समीकरण से: 1 mol C₆H₁₂O₆ के लिए 6 mol O₂ निकलती है","answer":"6 mol O₂"}$j$),
  (905,'govt_technical','nutr-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"प्रकाश संश्लेषण के लिए पौधे को सबसे पहले किसकी आवश्यकता होती है?","options":["CO₂ और पानी","नाइट्रोजन गैस","मिट्टी का तेल","नमक"],"answer":0,"explanation":"प्रकाश संश्लेषण में पौधे CO₂ और पानी का उपयोग करते हैं, जिसके लिए प्रकाश भी चाहिए।"},{"q":"स्कर्वी रोग किस विटामिन की कमी से होता है?","options":["विटामिन C","विटामिन D","विटामिन A","विटामिन B₁"],"answer":0,"explanation":"विटामिन C (एस्कॉर्बिक अम्ल) की कमी से स्कर्वी होता है।"}]}$j$),
  (905,'govt_basic','nutr-concept','concept',1,'पोषण',$j${"note":"परीक्षा में पोषक तत्वों के स्रोत और उनकी कमी के रोग पूछे जाते हैं।","text":"संतुलित आहार में कार्बोहाइड्रेट, प्रोटीन, वसा, विटामिन और खनिज होते हैं। कार्बोहाइड्रेट ऊर्जा देते हैं, प्रोटीन शरीर बनाते हैं, और वसा भी ऊर्जा देती है।"}$j$),
  (905,'govt_basic','nutr-formula','formula',2,'पोषक तत्व और कमी',$j${"formula":"विटामिन D की कमी = रिकेट्स · आयोडीन की कमी = घेंघा (गॉइटर)","explanation":"आयोडीन की कमी से थायरॉइड बढ़ जाता है"}$j$),
  (905,'govt_basic','nutr-example','example',3,'उदाहरण',$j${"question":"बच्चों में हड्डियाँ टेढ़ी होना किस विटामिन की कमी से होता है?","solution":"विटामिन D की कमी से हड्डियाँ कमजोर और टेढ़ी होती हैं (रिकेट्स)","answer":"विटामिन D"}$j$),
  (905,'govt_basic','nutr-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"शरीर का निर्माण मुख्य रूप से किस पोषक तत्व से होता है?","options":["प्रोटीन","विटामिन","खनिज लवण","पानी"],"answer":0,"explanation":"प्रोटीन ऊतकों और कोशिकाओं के निर्माण में मदद करता है।"},{"q":"आयोडीन की कमी से कौन सा रोग होता है?","options":["घेंघा (गॉइटर)","स्कर्वी","रतौंधी","रिकेट्स"],"answer":0,"explanation":"आयोडीन की कमी से थायरॉइड ग्रंथि बढ़ जाती है, जिसे घेंघा कहते हैं।"}]}$j$),
  (905,null,'nutr-diagram','svg',5,'प्रकाश संश्लेषण',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='40' cy='30' r='14' fill='#fde047'/><text x='40' y='58' text-anchor='middle' fill='#64748b' font-size='11'>सूर्य</text><rect x='120' y='40' width='60' height='50' fill='#86efac' rx='6'/><text x='150' y='68' text-anchor='middle' fill='#0f172a' font-size='11'>पत्ती</text><text x='80' y='80' fill='#64748b' font-size='11'>CO₂+H₂O</text><text x='200' y='80' fill='#64748b' font-size='11'>ग्लूकोज़+O₂</text><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>पत्ती में प्रकाश संश्लेषण</text></svg>","caption":"पत्तियाँ सूर्य के प्रकाश से भोजन बनाती हैं और ऑक्सीजन छोड़ती हैं"}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, exam_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi',
  case
    when s.level_id = 'govt_technical' then array['rrb-je-cbt1','rrb-je-cbt2','ssc-je-paper1']::text[]
    when s.level_id = 'govt_basic' then array['rrb-ntpc-graduate-cbt-1','rrb-ntpc-graduate-cbt-2','rrb-ntpc-ug-cbt-1','rrb-ntpc-ug-cbt-2']::text[]
    else '{}'::text[]
  end,
  'general-science', 'medium', md5(s.body::text)
from src s
on conflict do nothing;
